from pathlib import Path
import json,html
root=Path(__file__).resolve().parent
m=json.loads((root/'manifest.json').read_text(encoding='utf-8'))
assets=m['assets']
def esc(s):return html.escape(str(s),quote=True)
categories={'world-boss':'World boss','bosses':'Chefes','heroes':'Protagonistas','companions':'Companheiros','npcs':'NPCs','enemies':'Inimigos','scenes':'Cenários','station':'Estação','buildings':'Construções','relics':'Relíquias e recursos','props':'Objetos','hud':'HUD','controls':'Controles','effects':'Efeitos','terrain':'Terreno','atlases':'Folhas completas'}
cards=[]
for cat,label in categories.items():
    group=[a for a in assets if a['category']==cat]
    if cat=='bosses': group=sorted(group,key=lambda a:0 if a['id'].startswith(('boss-04','boss-05','boss-06','boss-07','boss-08')) else 1)
    card=''
    for a in group:
        note='Repouso e impacto · movimento procedural' if a['kind']=='actor' else 'Efeito em 6 quadros · movimento procedural' if a['kind']=='effect' else 'Arte estática'
        card+=f'<article class="card" data-title="{esc(a["title"].lower())}"><div class="art"><canvas data-id="{a["id"]}" width="{a["width"]}" height="{a["height"]}" style="width:min(100%,{a["width"]*2}px)" aria-label="{esc(a["title"])}"></canvas></div><div class="info"><h3>{esc(a["title"])}</h3><p>{a["width"]} × {a["height"]} px · {a["frames"]} quadros</p><p class="note">{note}</p><div class="links"><a href="{a["aseprite"]}" download>Aseprite ↓</a><a href="{a["png"]}" target="_blank">PNG</a><a href="{a["sheet"]}" target="_blank">Spritesheet</a><a href="{a["metadata"]}" target="_blank">JSON</a></div></div></article>'
    cards.append(f'<section data-category="{cat}"><h2>{label} <span>{len(group)} arquivos</span></h2><div class="grid {cat}">{card}</div></section>')
page="""<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agents Bar • Aseprite v03</title><style>
:root{--bg:#101623;--panel:#1b2536;--art:#27364b;--text:#edf1f8;--muted:#b1bfd0;--line:#3a4a62;--accent:#f0c473;color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.6 system-ui,sans-serif}body.light{--bg:#eaf0f5;--panel:#fff;--art:#bcc9d6;--text:#142339;--muted:#486079;--line:#a2b4c7;--accent:#785315;color-scheme:light}header,main{max-width:1500px;margin:auto;padding:32px}header{padding-top:60px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.2em;color:var(--accent)}h1{font-size:clamp(34px,5vw,64px);line-height:1.08;margin:18px 0}header p{color:var(--muted);max-width:900px}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0}.stats span{border:1px solid var(--line);border-radius:10px;padding:12px 18px}.stats strong{font-size:26px;margin-right:8px}.tools{position:sticky;top:0;z-index:3;display:flex;flex-wrap:wrap;gap:10px;background:var(--bg);padding:14px 0;border-bottom:1px solid var(--line)}button,select,input{font:inherit;color:var(--text);background:var(--panel);border:1px solid var(--line);padding:8px 12px;border-radius:7px}button,select{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:3px}h2{font-size:26px;margin:40px 0 20px}h2 span{font-size:13px;font-weight:400;color:var(--muted);margin-left:12px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}.art{height:330px;display:flex;align-items:center;justify-content:center;background:var(--art);padding:16px;overflow:auto}.art canvas{image-rendering:pixelated;max-height:100%;object-fit:contain;aspect-ratio:auto}.info{padding:16px}h3{font-size:17px;margin:0}.info p{margin:5px 0;color:var(--muted);font-size:13px}.note{font-size:12px!important}.links{display:flex;gap:15px;flex-wrap:wrap;margin-top:14px}a{color:var(--accent);font-size:13px}.world-boss,.scenes,.station{grid-template-columns:1fr}.world-boss .art{height:620px}.scenes .art,.station .art{height:auto;min-height:180px}.atlases{grid-template-columns:repeat(2,minmax(0,1fr))}.atlases .art{height:auto;min-height:300px}.relics,.controls,.hud,.effects,.terrain,.props{grid-template-columns:repeat(4,minmax(0,1fr))}.relics .art,.controls .art,.hud .art,.effects .art,.terrain .art,.props .art{height:190px}.notice{background:var(--panel);border-left:3px solid var(--accent);padding:20px;margin-top:40px;color:var(--muted)}footer{padding:35px 0;color:var(--muted)}[hidden]{display:none!important}@media(max-width:950px){.grid,.relics,.controls,.hud,.effects,.terrain,.props{grid-template-columns:repeat(2,minmax(0,1fr))}.world-boss,.scenes,.station{grid-template-columns:1fr}}@media(max-width:600px){main,header{padding:20px 14px}.grid{grid-template-columns:1fr}.world-boss .art{height:360px}.art{height:300px}}
</style></head><body><header><div class="eyebrow">Agents Bar / produção Aseprite / v03</div><h1>Os colossos chegaram.</h1><p>Cinco novos chefes, um world boss e o kit completo em arquivos Aseprite editáveis. Paleta indexada de 64 entradas, pixels em resolução nativa, corpo e luz em camadas separadas.</p><div class="stats"><span><strong>119</strong> arquivos Aseprite</span><span><strong>24</strong> personagens com idle/hit</span><span><strong>75</strong> elementos separados</span><span><strong>6</strong> novos colossos</span></div><p>Os desenhos-base foram gerados por IA. O tratamento dos pixels, recortes, paleta, camadas e movimentos simples foram executados no Aseprite por scripts. Esta entrega ainda não contém caminhada e ataques articulados.</p></header><main><div class="tools"><select id="category" aria-label="Categoria"><option value="all">Todas as categorias</option>OPTIONS</select><input id="search" placeholder="Buscar personagem ou item" aria-label="Buscar"><button id="play">Animar repouso</button><button id="hit">Animar impacto</button><button id="pause">Pausar</button><button id="theme">Fundo claro</button></div>CARDS<div class="notice"><strong>Produção técnica conferida; aceite no jogo pendente.</strong><br>As animações de repouso, impacto e efeitos são movimentos procedurais básicos, não animações articuladas desenhadas quadro a quadro. Os fundos continuam achatados, as peças de terreno são decorativas e os controles ainda precisam de ligação ao jogo. As barras de HUD mantêm preenchimento ilustrado. O aplicativo existente não foi alterado por este pacote.</div><footer><a href="README.md">Como usar</a> · <a href="BOSSES.md">Identidades e proposta de mecânicas</a> · <a href="manifest.json">Inventário e verificação</a> · <a href="boss-prompts.json">Prompts das novas bases</a><p>Galeria offline · sem bibliotecas externas · 26/10/2026</p></footer></main><script>
const assets=DATA;const map=new Map(assets.map(a=>[a.id,a]));let mode='paused',start=performance.now();
const visible=new Set();const records=[];
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)visible.add(e.target);else visible.delete(e.target)}));
document.querySelectorAll('canvas').forEach(c=>{const a=map.get(c.dataset.id),im=new Image();const r={c,a,im};records.push(r);im.onload=()=>c.getContext('2d').drawImage(im,0,0,a.width,a.height,0,0,a.width,a.height);im.src=a.sheet;observer.observe(c)});
function tick(t){for(const r of records){if(!visible.has(r.c)||!r.im.complete||!r.im.naturalWidth)continue;let frame=0;if(mode!=='paused'&&r.a.frames>1){const hit=mode==='hit'&&r.a.kind==='actor';const count=hit?4:r.a.kind==='actor'?8:6;frame=Math.floor((t-start)/(hit?80:r.a.kind==='effect'?75:125))%count+(hit?8:0)}const ctx=r.c.getContext('2d');ctx.clearRect(0,0,r.a.width,r.a.height);ctx.imageSmoothingEnabled=false;ctx.drawImage(r.im,frame*r.a.width,0,r.a.width,r.a.height,0,0,r.a.width,r.a.height)}requestAnimationFrame(tick)}requestAnimationFrame(tick);
document.getElementById('play').onclick=()=>{mode='idle';start=performance.now()};document.getElementById('hit').onclick=()=>{mode='hit';start=performance.now()};document.getElementById('pause').onclick=()=>{mode='paused'};
document.getElementById('theme').onclick=e=>{const on=document.body.classList.toggle('light');e.target.textContent=on?'Fundo escuro':'Fundo claro'};
function filter(){const cat=document.getElementById('category').value,q=document.getElementById('search').value.toLocaleLowerCase();document.querySelectorAll('section').forEach(s=>{let shown=0;s.querySelectorAll('.card').forEach(c=>{c.hidden=!c.dataset.title.includes(q);if(!c.hidden)shown++});s.hidden=(cat!=='all'&&cat!==s.dataset.category)||!shown})}document.getElementById('category').onchange=filter;document.getElementById('search').oninput=filter;
</script></body></html>"""
page=page.replace('OPTIONS',''.join(f'<option value="{k}">{v}</option>' for k,v in categories.items())).replace('CARDS',''.join(cards)).replace('DATA',json.dumps(assets,ensure_ascii=False))
(root/'index.html').write_text(page,encoding='utf-8')
print('Gallery written:',len(assets),'cards')

